public class PropertySearchService
{
    public IEnumerable<Property> Search(string? location, DateOnly? from, DateOnly? to, decimal? maxPrice)
    {
        return _properties.Where(p =>
            (location == null || p.Address.Contains(location)) &&
            (!maxPrice.HasValue || p.PricePerNight <= maxPrice) &&
            IsAvailable(p, from, to));
    }

    private bool IsAvailable(Property p, DateOnly? from, DateOnly? to)
    {
        if (!from.HasValue || !to.HasValue) return true;
        return !p.Bookings.Any(b =>
            b.Status == BookingStatus.Confirmed &&
            b.CheckIn < to && b.CheckOut > from);
    }
}

public class DynamicPricingService
{
    public decimal CalculatePrice(Property property, DateOnly from, DateOnly to)
    {
        decimal basePrice = property.PricePerNight;
        int nights = to.DayNumber - from.DayNumber;
        decimal total = basePrice * nights;

        // Weekend surcharge
        for (var d = from; d < to; d = d.AddDays(1))
        {
            if (d.DayOfWeek is DayOfWeek.Friday or DayOfWeek.Saturday)
                total += basePrice * 0.2m;
        }

        // Long-stay discount
        if (nights >= 7) total *= 0.9m;
        if (nights >= 30) total *= 0.8m;

        return total;
    }
}
